54	        result.put("name", skill.getName());
55	        result.put("description", skill.getDescription());
56	        result.put("creatorId", skill.getCreatorId());
57	        result.put("status", skill.getStatus());
58	        result.put("createdAt", skill.getCreatedAt());
59	        result.put("updatedAt", skill.getUpdatedAt());
60	        result.put("files", files);
61	
62	        return ApiResponse.success(result);
